import java.util.Scanner;

public class Main {
    public static void main(String[] args) {
        try (Scanner input = new Scanner(System.in)) {
            String text = input.nextLine().strip();
            try {
                int count = Integer.parseInt(text);
                if (count < 1) {
                    System.out.println("Positive count required");
                } else {
                    System.out.println("Accepted " + count);
                }
            } catch (NumberFormatException ex) {
                System.out.println("Whole number required");
            }
        }
    }
}

import java.io.IOException;
import java.nio.charset.StandardCharsets;
import java.nio.file.Files;
import java.nio.file.Path;

public class Main {
    public static void main(String[] args) throws IOException {
        String title = "رحلة في البرمجة";
        Path card = Files.createTempFile("java-book-", ".txt");
        try {
            Files.writeString(card, title, StandardCharsets.UTF_8);
            String restored = Files.readString(card, StandardCharsets.UTF_8);
            System.out.println(title.equals(restored));
        } finally {
            Files.deleteIfExists(card);
        }
    }
}

public class Main {
    static boolean canBorrow(String borrower) {
        return borrower.isEmpty();
    }

    static void check(String name, boolean actual, boolean expected) {
        if (actual != expected) {
            throw new AssertionError(name);
        }
    }

    public static void main(String[] args) {
        check("available", canBorrow(""), true);
        check("loaned", canBorrow("Sara"), false);
        System.out.println("2 checks passed");
    }
}
